function quoteTable(a) { $('#quote-table').innerHTML = a.length ? `<div class="table-wrap"><table><thead><tr><th>Número</th><th>Cliente</th><th>Data</th><th>Validade</th><th>Total</th><th>Status</th><th>Ações</th></tr></thead><tbody>${a.map(x => `<tr><td>${x.number}</td><td>${esc(entityName('clients', x.clientId))}</td><td>${date(x.date)}</td><td>${date(x.validity)}</td><td>${currency(x.total)}</td><td>${badge(x.status)}</td><td><div class="row-actions"><button class="btn sm" data-qview="${x.id}">Visualizar</button><button class="btn sm" data-qedit="${x.id}">Editar</button><button class="btn sm" data-qdup="${x.id}">Duplicar</button>${x.status !== 'Aprovado' ? `<button class="btn sm" data-approve="${x.id}">Aprovar</button>` : ''}<button class="btn sm" data-convert="${x.id}">Converter em OS</button></div></td></tr>`).join('')}</tbody></table></div>` : '<div class="panel empty">Nenhum orçamento cadastrado.</div>'; $$('[data-qedit]').forEach(b => b.onclick = () => quoteForm(b.dataset.qedit)); $$('[data-qview]').forEach(b => b.onclick = () => printQuote(b.dataset.qview)); $$('[data-qdup]').forEach(b => b.onclick = () => duplicateQuote(b.dataset.qdup)); $$('[data-approve]').forEach(b => b.onclick = () => { StorageService.update('quotes', b.dataset.approve, { status: 'Aprovado', approvedAt: now() }); render(); toast('Orçamento aprovado') }); $$('[data-convert]').forEach(b => b.onclick = () => convertQuote(b.dataset.convert)) }
