function bindQuoteItems() { $$('.quote-item [data-k="type"]').forEach(s => s.onchange = () => { const row = s.closest('.quote-item'), sel = row.querySelector('[data-k="itemId"]'), c = s.value === 'Material' ? 'products' : 'services'; sel.innerHTML = `<option value="">Item livre</option>${options(c)}` }); $$('.quote-item [data-k="itemId"]').forEach(s => s.onchange = () => { const row = s.closest('.quote-item'), c = row.querySelector('[data-k="type"]').value === 'Material' ? 'products' : 'services', x = StorageService.getById(c, s.value); if (x) { row.querySelector('[data-k="unitPrice"]').value = x.price || 0; row.querySelector('[data-k="description"]').value = x.name; row.querySelector('[data-k="unit"]').value = x.unit || 'un'; calcQuote() } }); bindRemove() }
