function quoteTotals(items, discount) { const services = items.filter(x => x.type === 'Serviço').reduce((s, x) => s + x.total, 0), materials = items.filter(x => x.type === 'Material').reduce((s, x) => s + x.total, 0), subtotal = services + materials, total = Math.max(0, subtotal - discount), cost = items.reduce((s, x) => s + x.cost, 0); return { servicesTotal: services, materialsTotal: materials, subtotal, total, cost, margin: total - cost } }
