function finishOrder(i) { const o = StorageService.getById('orders', i); if (!(o.items || []).length) return toast('Registre ao menos um serviço ou material antes de finalizar.', true); confirmAction('Finalizar esta OS? O histórico será preservado.', () => { StorageService.update('orders', i, { status: 'Concluída', completedAt: now() }); closeModal(); render(); toast('OS finalizada') }) }
function deductStock(i) { const o = StorageService.getById('orders', i); if (o.stockDeducted) return toast('A baixa desta OS já foi realizada.', true); const mats = (o.items || []).filter(x => x.type === 'Material' && x.itemId); for (const m of mats) { const p = StorageService.getById('products', m.itemId); if (!p || num(p.stock) < num(m.quantity)) return toast(`Estoque insuficiente: ${m.description}`, true) } for (const m of mats) { const p = StorageService.getById('products', m.itemId); StorageService.update('products', p.id, { stock: num(p.stock) - num(m.quantity) }); StorageService.create('stockMoves', { productId: p.id, type: 'Uso em OS', quantity: num(m.quantity), date: now().slice(0, 10), responsible: entityName('technicians', o.technicianId), reason: 'Material utilizado em serviço', reference: o.number, serviceOrderId: o.id }) } StorageService.update('orders', i, { stockDeducted: true }); closeModal(); render(); toast('Baixa de estoque concluída') }
