async function importFile(e) { const file = e.target.files[0]; if (!file) return; try { const data = JSON.parse(await file.text()); if (!StorageService.validate(data)) throw Error(); const summary = collections.map(c => `${c}: ${data[c].length}`).join(' · '); confirmAction(`Backup válido (${summary}). O estado atual será baixado antes da substituição. Continuar?`, () => { exportBackup(); StorageService.importBackup(data); render(); toast('Backup restaurado com sucesso') }) } catch { toast('Arquivo inválido. Nenhum dado foi alterado.', true) } finally { e.target.value = '' } }
